const D = { energy:.6, density:.55, scale:1, speed:1, hue:210, x:.5, y:.5, style:'plate', seed:0, alpha:100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const u = Math.min(width, height);
const style = P.style, sd = (P.seed | 0);
const fr = i => { const s = Math.sin(i * 127.1 + sd * 311.7) * 43758.5453; return s - Math.floor(s); };

// ---- cached faint deep-field starfield (luminance floor, never pure black) ----
const bgKey = width + 'x' + height + '|' + style + '|' + sd;
if (S.bgKey !== bgKey) {
  S.bgKey = bgKey;
  const BW = Math.max(360, Math.min(640, Math.round(width / 2.6)));
  const BH = Math.max(120, Math.round(BW * height / width));
  if (!S.bg || S.bgw !== BW || S.bgh !== BH) { S.bg = createGraphics(BW, BH); S.bg.pixelDensity(1); S.bgw = BW; S.bgh = BH; }
  const bg = S.bg; bg.loadPixels(); const pb = bg.pixels;
  const fg = i => { const s = Math.sin(i * 71.3 + sd * 51.7) * 33417.2; return s - Math.floor(s); };
  // toned deep-field ground per style
  let gr, gg, gb;
  if (style === 'xray') { gr = 4; gg = 10; gb = 14; }
  else if (style === 'nocturne') { gr = 6; gg = 7; gb = 18; }
  else if (style === 'isophote') { gr = 8; gg = 9; gb = 12; }
  else if (style === 'survey') { gr = 5; gg = 6; gb = 12; }
  else { gr = 7; gg = 8; gb = 14; }
  for (let j = 0; j < BH; j++) for (let i = 0; i < BW; i++) {
    const o = 4 * (j * BW + i);
    // very faint large-scale gradient so it's never flat/dead
    const fx = i / BW - 0.5, fy = j / BH - 0.5;
    const grad = 1 + 0.5 * Math.exp(-(fx*fx+fy*fy)*2.2);
    pb[o] = gr*grad; pb[o+1] = gg*grad; pb[o+2] = gb*grad; pb[o+3] = 255;
  }
  // scatter faint background stars
  const NS = Math.round(BW * BH * 0.012);
  for (let k = 0; k < NS; k++) {
    const ii = (fg(k*3+1)*BW)|0, jj = (fg(k*3+2)*BH)|0, a = fg(k*3+3);
    const v = 60 + a*a*180; const o = 4*(jj*BW+ii);
    pb[o] = Math.min(255, pb[o]+v*0.9); pb[o+1] = Math.min(255, pb[o+1]+v*0.95); pb[o+2] = Math.min(255, pb[o+2]+v);
  }
  bg.updatePixels();
}

// ---- seed-deterministic galaxy sprite templates (7), rebuilt on seed/style ----
const TS = 128, NTPL = 7;
if (S.tplKey !== bgKey) {
  S.tplKey = bgKey; S.tpl = [];
  for (let ti = 0; ti < NTPL; ti++) {
    const gph = createGraphics(TS, TS); gph.pixelDensity(1);
    gph.loadPixels(); const q = gph.pixels;
    const morph = ti % 5; // 0 spiral,1 elliptical,2 edge-on,3 irregular,4 barred
    const rot = fr(ti*7+1) * 6.28318, arms = 2 + Math.floor(fr(ti*7+2)*3);
    const wind = 2.2 + fr(ti*7+3)*1.6, ell = 0.45 + fr(ti*7+4)*0.5;
    const clx = [], cly = [], clr = [];
    for (let c = 0; c < 5; c++) { clx.push((fr(ti*20+c*3+5)*2-1)*0.4); cly.push((fr(ti*20+c*3+6)*2-1)*0.4); clr.push(0.12+fr(ti*20+c*3+7)*0.18); }
    const ct = Math.cos(rot), st = Math.sin(rot);
    for (let j = 0; j < TS; j++) for (let i = 0; i < TS; i++) {
      let ex = (i/TS-0.5)*2, ey = (j/TS-0.5)*2;
      // rotate into galaxy frame
      let gx = ex*ct+ey*st, gy = -ex*st+ey*ct;
      const rr = Math.sqrt(gx*gx+gy*gy);
      let emit = 0, warm = 0.5;
      if (morph === 0 || morph === 4) {                    // spiral / barred
        const bulge = Math.exp(-rr*rr*7)*1.4; emit += bulge; warm = 0.8;
        const th = Math.atan2(gy, gx);
        let arm = 0;
        for (let a = 0; a < arms; a++) {
          const spiralTh = wind * Math.log(rr+0.06) + a*(6.2831/arms) + rot;
          let d = Math.cos(th - spiralTh); d = (d+1)*0.5; d = Math.pow(d, 8);
          arm = Math.max(arm, d);
        }
        const disk = Math.exp(-rr*3.0);
        emit += arm * disk * 1.3 * (rr>0.06?1:0);
        if (morph === 4) emit += Math.exp(-(gy*gy)*60 - Math.max(0,rr-0.35)*6)*0.9; // bar
        warm = 0.35 + bulge*0.5;                            // arms blue, bulge yellow
      } else if (morph === 1) {                            // elliptical (smooth, warm)
        const r2 = gx*gx + (gy/ell)*(gy/ell);
        emit = Math.exp(-r2*4.5)*1.6; warm = 0.85;
      } else if (morph === 2) {                            // edge-on disk + dust lane
        emit = Math.exp(-(gy*gy)*22 - (gx*gx)*2.4)*1.6;
        emit *= (1 - 0.7*Math.exp(-(gy*gy)*120));          // dark dust lane
        emit += Math.exp(-rr*rr*30)*0.7;                    // bulge
        warm = 0.7;
      } else {                                             // irregular clumps (blue)
        for (let c = 0; c < 5; c++) { const dx = gx-clx[c], dy = gy-cly[c]; emit += Math.exp(-(dx*dx+dy*dy)/(clr[c]*clr[c]))*0.8; }
        warm = 0.25;
      }
      // vignette to keep sprite circular
      emit *= Math.max(0, 1 - rr*rr*1.05);
      if (style === 'isophote') { const lv = 0.5+0.5*Math.cos(Math.min(1,emit)*20.0); emit = (emit>0.03?1:0)*(0.15+0.85*lv)*Math.min(1,emit*2.2); }
      let cr, cg, cb;
      if (style === 'xray') { const t = Math.min(1,emit); cr = t*t*160; cg = Math.pow(t,0.7)*230; cb = Math.pow(t,0.6)*255; }
      else if (style === 'nocturne') { const t = Math.min(1,emit); cr = t*90; cg = t*110; cb = t*t*255+t*40; }
      else if (style === 'survey') { const t = Math.min(1,emit); cr = (warm)*t*255; cg = t*t*180; cb = (1-warm)*t*255 + t*40; }
      else if (style === 'isophote') { const t = Math.min(1,emit); cr = t*130; cg = t*200; cb = t*255*0.9; }
      else { const t = Math.min(1,emit); // plate (natural)
        cr = t*(160+warm*95); cg = t*(150+warm*70); cb = t*(150+(1-warm)*105); }
      const o = 4*(j*TS+i);
      q[o] = Math.min(255,cr); q[o+1] = Math.min(255,cg); q[o+2] = Math.min(255,cb); q[o+3] = 255;
    }
    gph.updatePixels(); S.tpl.push(gph);
  }
}

// ---- seed-deterministic placements (rebuild on seed/count) ----
const NG = Math.round(10 + P.density * 30);
if (!S.gal || S.galSeed !== sd || S.galN !== NG) {
  S.galSeed = sd; S.galN = NG; S.gal = [];
  for (let i = 0; i < NG; i++) {
    S.gal.push({
      tpl: Math.floor(fr(i*9+1)*NTPL),
      bx: fr(i*9+2), by: fr(i*9+3),
      sz: 0.05 + Math.pow(fr(i*9+4), 1.8) * 0.28,          // few big, many small
      ang: fr(i*9+5)*6.28318,
      spin: (fr(i*9+6)-0.5)*0.16,
      dvx: (fr(i*9+7)-0.5)*0.5, dvy: (fr(i*9+8)-0.5)*0.5,
      dph: fr(i*9+9)*6.28318, twp: fr(i*9+10)*6.28318,
      br: 0.6 + fr(i*9+11)*0.5
    });
  }
}

// ---- draw ----
push();
if (P.alpha < 100) tint(0, 0, 100, P.alpha); image(S.bg, 0, 0, width, height); noTint();
pop();

const T = K.t * (0.4 + P.speed * 0.6);
push();
blendMode(ADD);
imageMode(CENTER);
const gal = S.gal;
for (let i = 0; i < gal.length; i++) {
  const G = gal[i];
  // slow drifting position (incommensurate) + gentle wander; wrap around frame
  let gx = (G.bx + (Math.sin(T*0.05*G.dvx + G.dph)*0.06 + T*0.006*G.dvx)) % 1.2;
  let gy = (G.by + (Math.cos(T*0.045*G.dvy + G.dph)*0.06 + T*0.005*G.dvy)) % 1.2;
  gx = ((gx % 1) + 1) % 1; gy = ((gy % 1) + 1) % 1;
  const cxp = (gx * 1.1 - 0.05 + (P.x - 0.5) * 0.2) * width;
  const cyp = (gy * 1.1 - 0.05 + (P.y - 0.5) * 0.2) * height;
  const sz = G.sz * u * (0.7 + P.scale * 0.9);
  const tw = 0.75 + 0.25*Math.sin(T*(0.5+G.twp*0.1) + G.twp) + K.pulse*0.12 + A.rms*0.3;
  const al = Math.min(100, (34 + P.energy*55) * G.br * tw) * (P.alpha/100);
  push();
  translate(cxp, cyp);
  rotate(G.ang + G.spin*T);
  tint(0, 0, 100, al);
  image(S.tpl[G.tpl], 0, 0, sz, sz);
  pop();
}
imageMode(CORNER);
blendMode(BLEND);
pop();
